const entrada = $('Webhook').first().json;
const clientes = Array.isArray(entrada.clientes)
  ? entrada.clientes
  : Array.isArray(entrada.body?.clientes)
    ? entrada.body.clientes
    : Array.isArray(entrada)
      ? entrada
      : [];

const csvBruto = $input.first().json.data ?? $input.first().json;
const csvTexto = typeof csvBruto === 'string' ? csvBruto : String(csvBruto);

const linhas = csvTexto.trim().split(/\r?\n/).slice(1);
const investimentos = linhas
  .map((linha) => {
    const [perfil, produto, minimo, rentabilidade] = linha.split(',');
    return {
      perfil: (perfil || '').trim(),
      produto: (produto || '').trim(),
      minimo: Number((minimo || '0').trim()),
      rentabilidade: (rentabilidade || '').trim(),
    };
  })
  .filter((item) => item.perfil && item.produto);

function saldoNumero(saldoTexto) {
  return Number(
    String(saldoTexto)
      .replace(/R\$\s?/g, '')
      .replace(/\./g, '')
      .replace(',', '.')
  );
}

return clientes.map((cliente) => {
  const saldo = saldoNumero(cliente.saldo);
  const perfilNorm = String(cliente.perfil || '').trim().toLowerCase();
  const opcoes = investimentos
    .filter((item) => item.perfil.toLowerCase() === perfilNorm)
    .filter((item) => saldo >= item.minimo);
  const escolha = opcoes[0] || investimentos.find((item) => item.perfil.toLowerCase() === perfilNorm);

  const prompt = [
    'Escreva um e-mail curto em portugues do Brasil para o cliente abaixo.',
    'Tom amigavel e profissional. Entre 4 e 8 linhas.',
    'Nao prometa lucro garantido. Nao use linguagem agressiva.',
    `Nome: ${cliente.nome}`,
    `Email: ${cliente.email}`,
    `Saldo: ${cliente.saldo}`,
    `Perfil: ${cliente.perfil}`,
    `Produto recomendado: ${escolha?.produto || 'indisponivel'}`,
    `Rentabilidade: ${escolha?.rentabilidade || 'n/a'}`,
    `Minimo do produto: R$ ${escolha?.minimo ?? 0}`,
    'Devolva so o corpo do e-mail, sem assunto e sem markdown.',
  ].join('\n');

  return {
    json: {
      email_to: cliente.email,
      nome: cliente.nome,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      produto: escolha?.produto || null,
      rentabilidade: escolha?.rentabilidade || null,
      minimo: escolha?.minimo ?? null,
      chatInput: prompt,
    },
  };
});

const cruzados = $('Cruzar perfil').all();
const gerados = $input.all();

return gerados.map((item, index) => {
  const base = cruzados[index]?.json || {};
  const parts = item.json?.candidates?.[0]?.content?.parts || [];
  const texto = parts.map((p) => p.text || '').join('\n').trim();
  return {
    json: {
      email_to: base.email_to,
      nome: base.nome,
      saldo: base.saldo,
      perfil: base.perfil,
      produto: base.produto,
      rentabilidade: base.rentabilidade,
      assunto: `Sugestao de investimento para ${base.nome}`,
      corpo_email: texto || 'Nao foi possivel gerar o e-mail.',
    },
  };
});
